    facts:[["Preliminary ceasefire","8 June 1947"],["Final instruments","18 July 1947"],["Host","Portugal"],["Mediator","António de Oliveira Salazar's government"],["British prime minister","Clement Attlee"],["Principal negotiating powers","Britain, Germany, Italy, and Japan"],["United States","Absent"],["Result","Five-system postwar order"]]
